export interface ConnectivityTestConfig {
  /** Whether the analysis should skip firewall checking. Default value is false. */
  bypassFirewallChecks?: boolean | Computed<boolean>;
  /** The user-supplied description of the Connectivity Test. Maximum of 512 characters. */
  description?: string | Computed<string>;
  /** Source or destination of the Connectivity Test. */
  destination?: ConnectivityTest_Destination | Computed<ConnectivityTest_Destination>;
  /** Resource labels to represent user-provided metadata. */
  labels?: Record<string, string> | Computed<Record<string, string>>;
  /** Identifier. Unique name of the resource using the form: `projects/{project_id}/locations/global/connectivityTests/{test_id}` */
  name?: string | Computed<string>;
  /** Results of active probing from the last run of the test. */
  probingDetails?: ConnectivityTest_ProbingDetails | Computed<ConnectivityTest_ProbingDetails>;
  /** IP Protocol of the test. When not provided, "TCP" is assumed. */
  protocol?: string | Computed<string>;
  /** Results of the configuration analysis from the last run of the test. */
  reachabilityDetails?: ConnectivityTest_ReachabilityDetails | Computed<ConnectivityTest_ReachabilityDetails>;
  /** Other projects that may be relevant for reachability analysis. This is applicable to scenarios where a test can cross project boundaries. */
  relatedProjects?: string[] | Computed<string[]>;
  /** Results of the configuration analysis from the last run of the test. */
  returnReachabilityDetails?: ConnectivityTest_ReachabilityDetails | Computed<ConnectivityTest_ReachabilityDetails>;
  /** Whether run analysis for the return path from destination to source. Default value is false. */
  roundTrip?: boolean | Computed<boolean>;
  /** Source or destination of the Connectivity Test. */
  source?: ConnectivityTest_Destination | Computed<ConnectivityTest_Destination>;
}

export interface ConnectivityTestAttrs {
  /** Whether the analysis should skip firewall checking. Default value is false. */
  bypassFirewallChecks: boolean;
  /** Output only. The time the test was created. */
  createTime: string;
  /** The user-supplied description of the Connectivity Test. Maximum of 512 characters. */
  description: string;
  /** Source or destination of the Connectivity Test. */
  destination: ConnectivityTest_Destination;
  /** Output only. The display name of a Connectivity Test. */
  displayName: string;
  /** Resource labels to represent user-provided metadata. */
  labels: Record<string, string>;
  /** Identifier. Unique name of the resource using the form: `projects/{project_id}/locations/global/connectivityTests/{test_id}` */
  name: string;
  /** Results of active probing from the last run of the test. */
  probingDetails: ConnectivityTest_ProbingDetails;
  /** IP Protocol of the test. When not provided, "TCP" is assumed. */
  protocol: string;
  /** Results of the configuration analysis from the last run of the test. */
  reachabilityDetails: ConnectivityTest_ReachabilityDetails;
  /** Other projects that may be relevant for reachability analysis. This is applicable to scenarios where a test can cross project boundaries. */
  relatedProjects: string[];
  /** Results of the configuration analysis from the last run of the test. */
  returnReachabilityDetails: ConnectivityTest_ReachabilityDetails;
  /** Whether run analysis for the return path from destination to source. Default value is false. */
  roundTrip: boolean;
  /** Source or destination of the Connectivity Test. */
  source: ConnectivityTest_Destination;
  /** Output only. The time the test's configuration was updated. */
  updateTime: string;
}

